```json
{
  "root_causes": [
    {
      "service": "checkout",
      "fault_kind": "network_delay",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(c.duration)/1e6,1) AS client_ms, round(avg(s.duration)/1e6,2) AS server_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='checkout' AND s.service_name='payment' GROUP BY 1,2",
          "claim": "In the incident window, checkout's client Charge spans average about 442 ms while payment's server spans stay about 1.2 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name AS caller, s.service_name AS callee, count(*) AS n, round(avg(c.duration)/1e6,2) AS client_ms, round(avg(s.duration)/1e6,2) AS server_ms FROM normal_traces c JOIN normal_traces s ON s.parent_span_id = c.span_id WHERE c.service_name='checkout' AND s.service_name='payment' GROUP BY 1,2",
          "claim": "In the normal period the same checkout-to-payment Charge call averages about 2.5 ms client and 1.2 ms server."
        }
      ]
    },
    {
      "service": "quote",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, metric, date_trunc('minute', time) AS m, count(*) AS n, round(avg(value),3) AS v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'quote%' AND metric = 'k8s.container.restarts' GROUP BY 1,2,3 ORDER BY 3",
          "claim": "The quote pod's container restart counter goes from 0 in the normal period to 1 at the start of the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, date_trunc('minute', time) AS m, count(*) AS n FROM abnormal_traces WHERE service_name = 'quote' GROUP BY 1,2 ORDER BY 2",
          "claim": "Quote emits no spans in the 05:14 minute, then recovers, consistent with a brief outage after its restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "quote",
      "to": "shipping",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS parent_svc, c.service_name AS child_svc, count(*) AS n, round(avg(c.duration)/1e6,2) AS child_ms, round(avg(p.duration)/1e6,2) AS parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id WHERE p.service_name='shipping' AND c.service_name='quote' GROUP BY 1,2",
          "claim": "Shipping's calls into quote and its /get-quote spans slow to about 13 ms in the first minute, when quote restarts."
        }
      ]
    },
    {
      "from": "shipping",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, date_trunc('minute', time) AS m, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms, round(max(duration)/1e6,1) AS max_ms FROM abnormal_traces WHERE service_name IN ('shipping') GROUP BY 1,2 ORDER BY 2",
          "claim": "Shipping's /get-quote latency and span volume shift during the quote gap, and checkout calls shipping in these traces."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, date_trunc('minute', time) AS m, count(*) AS n, round(avg(duration)/1e6,1) AS avg_ms, round(max(duration)/1e6,1) AS max_ms FROM abnormal_traces WHERE service_name IN ('checkout') GROUP BY 1,2 ORDER BY 2",
          "claim": "Checkout's own span latency rises to about 442 ms from the delayed payment calls, in the same window as frontend's slowdown."
        }
      ]
    }
  ]
}
